import mongoose from "mongoose";

const searchEventSchema = new mongoose.Schema(
    {
        /**
         * Shopify store domain.
         *
         * Example:
         * my-store.myshopify.com
         */
        shop: {
            type: String,
            required: [true, "Shop identifier is required"],
            index: true,
            trim: true,
            lowercase: true,
        },

        /**
         * Unique event ID generated by Shopify Web Pixel
         * or frontend.
         *
         * Prevents duplicate events.
         */
        eventId: {
            type: String,
            required: [true, "Event ID is required"],
            trim: true,
        },

        /**
         * Customer/browser identifier.
         */
        clientId: {
            type: String,
            default: null,
            index: true,
            trim: true,
        },

        /**
         * Type of event.
         */
        eventType: {
            type: String,
            required: [true, "Event type is required"],
            enum: [
                "search",
                "click",
                "product_click",
                "add_to_cart",
                "purchase",
                "product_view",
            ],
            index: true,
        },

        /**
         * Original Shopify/Web Pixel event name.
         */
        eventName: {
            type: String,
            required: [true, "Event name is required"],
            trim: true,
        },

        /**
         * Original search query.
         */
        query: {
            type: String,
            default: null,
            trim: true,
        },

        /**
         * Normalized search query.
         *
         * Example:
         * " Running   Shoes "
         * ->
         * "running shoes"
         */
        normalizedQuery: {
            type: String,
            default: null,
            index: true,
            trim: true,
        },

        /**
         * Number of products returned by search.
         *
         * 0 = zero-result search.
         *
         * null = result count was not captured.
         */
        resultCount: {
            type: Number,
            default: null,
            min: 0,
        },

        /**
         * ID of the search that initiated
         * the customer journey.
         */
        queryId: {
            type: String,
            default: null,
            index: true,
            trim: true,
        },

        /**
         * Shopify product ID.
         */
        productId: {
            type: String,
            default: null,
            index: true,
            trim: true,
        },

        /**
         * Shopify variant ID.
         */
        variantId: {
            type: String,
            default: null,
            trim: true,
        },

        /**
         * Shopify order ID.
         */
        orderId: {
            type: String,
            default: null,
            index: true,
            trim: true,
        },

        /**
         * Monetary value.
         */
        value: {
            type: Number,
            default: 0,
            min: 0,
        },

        /**
         * Currency.
         *
         * Example:
         * USD, EUR, INR
         */
        currency: {
            type: String,
            default: null,
            trim: true,
            uppercase: true,
        },

        /**
         * Event occurrence timestamp.
         */
        occurredAt: {
            type: Date,
            required: true,
            default: Date.now,
            index: true,
        },

        /**
         * Additional event metadata.
         */
        metadata: {
            type: mongoose.Schema.Types.Mixed,
            default: {},
        },
    },
    {
        timestamps: true,
        collection: "tbl_search_events",
    }
);

/**
 * Prevent duplicate events per shop.
 */
searchEventSchema.index(
    {
        shop: 1,
        eventId: 1,
    },
    {
        unique: true,
    }
);

searchEventSchema.index(
    {
        shop: 1,
        orderId: 1,
    },
    {
        unique: true,
        partialFilterExpression: {
            "metadata.verifiedOrder": true,
            orderId: { $type: "string" },
        },
    }
);

/**
 * Date filtering.
 */
searchEventSchema.index({
    shop: 1,
    eventType: 1,
    occurredAt: -1,
});

/**
 * Search query aggregation.
 */
searchEventSchema.index({
    shop: 1,
    normalizedQuery: 1,
    occurredAt: -1,
});

/**
 * Customer journey attribution.
 */
searchEventSchema.index({
    shop: 1,
    clientId: 1,
    eventType: 1,
    occurredAt: -1,
});

/**
 * Product analytics.
 */
searchEventSchema.index({
    shop: 1,
    productId: 1,
    eventType: 1,
    occurredAt: -1,
});

/**
 * Zero-result search optimization.
 */
searchEventSchema.index({
    shop: 1,
    eventType: 1,
    resultCount: 1,
    occurredAt: -1,
});

/**
 * Query + result count aggregation.
 */
searchEventSchema.index({
    shop: 1,
    eventType: 1,
    normalizedQuery: 1,
    resultCount: 1,
    occurredAt: -1,
});

/**
 * Reuse existing model if already registered.
 */
const SearchEvent =
    mongoose.models.SearchEvent ||
    mongoose.model(
        "SearchEvent",
        searchEventSchema
    );

export default SearchEvent;
